// Combines apps-script/*.gs into one file, dist/EventHub.gs, so the team pastes a
// single file into the Apps Script editor (plus appsscript.json).
// Run: npm run bundle
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.join(root, 'apps-script');
const files = fs.readdirSync(src).filter((f) => f.endsWith('.gs')).sort();
let out = `/**
 * KarmaVerse EventHub: the whole backend in one file. Generated by
 * eventhub-sheets/scripts/bundle.mjs from apps-script/*.gs; edit those files, not this one.
 * Paste this into the Apps Script editor as a single file named EventHub.
 */
`;
for (const f of files) out += `\n// ==================== ${f} ====================\n\n` + fs.readFileSync(path.join(src, f), 'utf8');
fs.mkdirSync(path.join(root, 'dist'), { recursive: true });
fs.writeFileSync(path.join(root, 'dist', 'EventHub.gs'), out);
fs.copyFileSync(path.join(src, 'appsscript.json'), path.join(root, 'dist', 'appsscript.json'));
console.log(`dist/EventHub.gs: ${files.length} files, ${out.split('\n').length} lines`);
